\begin{tikzpicture}[x=1.25cm,y=0.8cm]
\definecolor{curveblue}{HTML}{268CFF}
\definecolor{tangentred}{HTML}{EF6068}
\definecolor{normalgreen}{HTML}{4F9B63}
\draw[->,black] (-0.4,0)--(3.4,0);
\draw[->,black] (0,-0.7)--(0,4.4);
\path (3.4,0) node[right,text=black,font=\fontsize{10}{12}\selectfont] {$x$};
\path (0,4.4) node[above,text=black,font=\fontsize{10}{12}\selectfont] {$y$};
\draw[curveblue,thick,domain=0.07:3.1,samples=90] plot (\x,{ln(\x)+2});
\draw[tangentred,thick] (-0.3,0.7)--(3.1,4.1);
\draw[normalgreen,thick] (-0.3,3.3)--(3.1,-0.1);
\fill[black] (1,2) circle (1.5pt);
\path (1,2) node[above left,text=black,font=\fontsize{10}{12}\selectfont] {$P(1,2)$};
\path (3.1,4.1) node[above left,text=black,font=\fontsize{10}{12}\selectfont] {Tangent};
\path (3.1,-0.1) node[below left,text=black,font=\fontsize{10}{12}\selectfont] {Normal};
\path (2.7,3) node[below,text=black,font=\fontsize{10}{12}\selectfont] {$y=\ln x+2$};
\end{tikzpicture}
